// Banque anglais (niveau B1 du CECRL) : temps, for/since, prépositions, modaux, conditionnels,
// passif, discours indirect, gérondif/infinitif, comparatifs, quantifieurs, articles, relatifs,
// question tags, phrasal verbs, verbes irréguliers, orthographe, faux amis, vocabulaire des
// finances publiques, de la fiscalité et de la comptabilité, traduction de phrases courtes.
BANK.push(
// --- Temps : présent, prétérit, present perfect, past perfect, futur ---
{id:"an2-001",t:"ang",q:"Complete: « Water … at 100 degrees Celsius. »",o:["is boiling","boiled","has boiled","boils"],a:3,e:"Present simple pour une vérité générale ou un fait scientifique.",s:"Banque anglais"},
{id:"an2-002",t:"ang",q:"Complete: « She usually … to work by bus, but today she … . »",o:["goes / is walking","is going / walks","goes / walking","go / is walking"],a:0,e:"Habitude (usually) : present simple ; action propre au moment présent (today) : present continuous.",s:"Banque anglais"},
{id:"an2-003",t:"ang",q:"Which sentence is correct?",o:["I am knowing the answer.","I knowing the answer.","I know the answer.","I am know the answer."],a:2,e:"Les verbes d'état (know, believe, understand, need, want) ne s'emploient normalement pas à la forme en -ing.",s:"Banque anglais"},
{id:"an2-004",t:"ang",q:"Complete: « I … him since we left university. »",o:["didn't see","haven't seen","don't see","wasn't seeing"],a:1,e:"Since + point de départ : present perfect, car la période se prolonge jusqu'à maintenant.",s:"Banque anglais"},
{id:"an2-005",t:"ang",q:"Complete: « She … for the ministry for ten years, and she still works there. »",o:["worked","works","had worked","has worked"],a:3,e:"Action commencée dans le passé et qui dure encore : present perfect + for. Le prétérit « worked » signifierait qu'elle n'y travaille plus.",s:"Banque anglais"},
{id:"an2-006",t:"ang",q:"Complete: « How long … English? – For three years now. »",o:["are you learning","do you learn","have you been learning","were you learning"],a:2,e:"How long + action qui dure encore : present perfect continuous (have been + -ing).",s:"Banque anglais"},
{id:"an2-007",t:"ang",q:"Complete: « I'm exhausted because I … all day. »",o:["have been work","have been working","had been working","am worked"],a:1,e:"Present perfect continuous : activité prolongée, qui vient de s'achever ou dure encore, dont on voit le résultat (la fatigue).",s:"Banque anglais"},
{id:"an2-008",t:"ang",q:"Complete: « When I arrived at the station, the train … already … . »",o:["had / left","has / left","is / leaving","did / leave"],a:0,e:"Past perfect (had + participe passé) : action antérieure à une autre action passée (arrived).",s:"Banque anglais"},
{id:"an2-009",t:"ang",q:"Which sentence is correct?",o:["I have seen her yesterday.","I saw her yesterday.","I have saw her yesterday.","I seen her yesterday."],a:1,e:"Avec un repère passé révolu (yesterday, last week, in 2020, ago), on emploie le prétérit, jamais le present perfect.",s:"Banque anglais"},
{id:"an2-010",t:"ang",q:"Complete: « While I … dinner, the phone rang. »",o:["were cooking","am cooking","was cooking","have cooked"],a:2,e:"Past continuous (was / were + -ing) pour l'action en cours, interrompue par une action brève au prétérit (rang). Avec I : was.",s:"Banque anglais"},
{id:"an2-011",t:"ang",q:"Complete: « Look at those dark clouds! It … rain. »",o:["goes to","is raining to","going to","is going to"],a:3,e:"Be going to : prédiction fondée sur un indice visible dans le présent (les nuages).",s:"Banque anglais"},
{id:"an2-012",t:"ang",q:"Complete: « I … my dentist at 4 pm tomorrow: the appointment is booked. »",o:["am seeing","saw","have seen","had seen"],a:0,e:"Present continuous à valeur de futur : rendez-vous ou arrangement déjà fixé.",s:"Banque anglais"},
{id:"an2-013",t:"ang",q:"Complete: « The train to Lyon … at 7.45 tomorrow morning, according to the timetable. »",o:["left","has left","leaves","had left"],a:2,e:"Present simple à valeur de futur pour un horaire officiel (timetable, programme).",s:"Banque anglais"},
{id:"an2-014",t:"ang",q:"Complete: « It's cold in here. – Wait, I … the window. »",o:["closed","will close","have closed","had closed"],a:1,e:"Will : décision prise au moment où l'on parle (offre spontanée).",s:"Banque anglais"},
{id:"an2-015",t:"ang",q:"Complete: « This is the first time I … to Ireland. »",o:["go","went","had been","have been"],a:3,e:"This is the first time + present perfect (et non le présent comme en français : « c'est la première fois que je vais… »).",s:"Banque anglais"},
{id:"an2-016",t:"ang",q:"Complete: « What … at the moment? – I'm reading the new circular. »",o:["are you doing","do you do","did you do","have you done"],a:0,e:"At the moment : present continuous. « What do you do? » demande la profession.",s:"Banque anglais"},
// --- For, since, during, while, by, until ---
{id:"an2-017",t:"ang",q:"Complete: « I fell asleep … the film. »",o:["for","since","during","while"],a:2,e:"During + nom (pendant un événement) ; while + sujet + verbe ; for + durée.",s:"Banque anglais"},
{id:"an2-018",t:"ang",q:"Complete: « I met him … I was living in London. »",o:["during","for","since","while"],a:3,e:"While + proposition (sujet + verbe) ; during + nom (during my stay).",s:"Banque anglais"},
{id:"an2-019",t:"ang",q:"Complete: « The tax office will be closed … three weeks in August. »",o:["for","since","during","ago"],a:0,e:"For + durée (combien de temps ?) ; during répond à « quand ? » (during August).",s:"Banque anglais"},
{id:"an2-020",t:"ang",q:"What's the English for: « Il travaille ici depuis trois mois. »",o:["He works here since three months.","He has worked here for three months.","He has worked here since three months.","He works here for three months."],a:1,e:"« Depuis » + durée : present perfect + for. Since s'emploie avec un point de départ (since March).",s:"Banque anglais"},
{id:"an2-021",t:"ang",q:"Complete: « Your tax return must be filed … 31 May at the latest. »",o:["until","since","by","in"],a:2,e:"By = au plus tard (échéance) ; until = jusqu'à (action ou état qui se prolonge jusqu'à ce moment).",s:"Banque anglais"},
{id:"an2-022",t:"ang",q:"Complete: « The office stays open … 6 pm, then it closes. »",o:["by","until","since","for"],a:1,e:"Until = jusqu'à (l'état se prolonge jusqu'à ce moment) ; by = au plus tard.",s:"Banque anglais"},
// --- Prépositions de temps et de lieu ---
{id:"an2-023",t:"ang",q:"Complete: « She lives … Paris. »",o:["in","at","on","to"],a:0,e:"In + ville, pays, région ; at + lieu précis (at the station, at the bus stop).",s:"Banque anglais"},
{id:"an2-024",t:"ang",q:"Complete: « Let's meet … the bus stop. »",o:["in","on","to","at"],a:3,e:"At : point précis, lieu de rendez-vous (at the bus stop, at the station).",s:"Banque anglais"},
{id:"an2-025",t:"ang",q:"Complete: « Her birthday is … 14 July. »",o:["in","at","on","by"],a:2,e:"On + date ou jour ; in + mois, année, saison ; at + heure.",s:"Banque anglais"},
{id:"an2-026",t:"ang",q:"Complete: « Owls hunt … night. »",o:["at","in","on","during"],a:0,e:"At night (sans article), mais in the morning, in the afternoon, in the evening.",s:"Banque anglais"},
{id:"an2-027",t:"ang",q:"Complete: « I'm not very good … cooking. »",o:["in","on","for","at"],a:3,e:"Good at / bad at + activité ou domaine.",s:"Banque anglais"},
{id:"an2-028",t:"ang",q:"Complete: « The price depends … the quantity ordered. »",o:["of","on","from","at"],a:1,e:"Depend on (et non « of ») : dépendre de.",s:"Banque anglais"},
{id:"an2-029",t:"ang",q:"Complete: « We arrived … the airport two hours before the flight. »",o:["to","on","by","at"],a:3,e:"Arrive at + lieu précis (station, airport) ; arrive in + ville ou pays ; jamais « arrive to ».",s:"Banque anglais"},
{id:"an2-030",t:"ang",q:"Complete: « She is married … a tax lawyer. »",o:["with","at","to","by"],a:2,e:"Be married to somebody (et non « with »).",s:"Banque anglais"},
{id:"an2-031",t:"ang",q:"Complete: « She goes to work … foot, but her husband goes … car. »",o:["by / on","on / by","on / in","by / by"],a:1,e:"On foot, mais by car, by bus, by train (sans article).",s:"Banque anglais"},
// --- Modaux ---
{id:"an2-032",t:"ang",q:"Complete: « You … smoke in the office: it is strictly forbidden. »",o:["mustn't","needn't","don't have to","can"],a:0,e:"Mustn't = interdiction ; needn't et don't have to = absence d'obligation.",s:"Banque anglais"},
{id:"an2-033",t:"ang",q:"Complete: « You … bring your passport: your identity card is enough. »",o:["mustn't","can't","needn't","shouldn't to"],a:2,e:"Needn't = ce n'est pas nécessaire ; mustn't exprimerait une interdiction.",s:"Banque anglais"},
{id:"an2-034",t:"ang",q:"Complete: « When I was younger, I … run for an hour without stopping. »",o:["can","must","may","could"],a:3,e:"Could : capacité dans le passé (prétérit de can).",s:"Banque anglais"},
{id:"an2-035",t:"ang",q:"Complete: « You look tired. You … go to bed earlier. »",o:["must to","should","ought","would"],a:1,e:"Should + base verbale : conseil. Ought est toujours suivi de to (you ought to go).",s:"Banque anglais"},
{id:"an2-036",t:"ang",q:"Complete: « Her car is in front of the house, so she … be at home. »",o:["must","can't","needn't","mustn't"],a:0,e:"Must : déduction quasi certaine ; can't : impossibilité logique.",s:"Banque anglais"},
{id:"an2-037",t:"ang",q:"Complete: « He … be the thief: he was with me all evening. »",o:["must","should","has to","can't"],a:3,e:"Can't : déduction négative (c'est impossible). Le contraire de must (déduction) est can't, pas mustn't.",s:"Banque anglais"},
{id:"an2-038",t:"ang",q:"Which sentence is a polite request for permission?",o:["May I leave early today?","Must I leave early today?","Should I leave early today?","Will I leave early today?"],a:0,e:"May I… ? (ou Could I… ? / Can I… ?) : demander la permission. Must = obligation, should = conseil.",s:"Banque anglais"},
{id:"an2-039",t:"ang",q:"Complete: « Take an umbrella: it … rain later, you never know. »",o:["must","might","has to","should to"],a:1,e:"Might : simple possibilité (peut-être). Must exprimerait une certitude ; should n'est jamais suivi de to.",s:"Banque anglais"},
{id:"an2-040",t:"ang",q:"Complete: « Yesterday I … work late because of the audit. »",o:["must","have to","had to","musted"],a:2,e:"Must n'a pas de prétérit : on emploie had to pour une obligation passée.",s:"Banque anglais"},
{id:"an2-041",t:"ang",q:"Complete: « You … have told me! I would have helped you. »",o:["must","can","should","will"],a:2,e:"Should have + participe passé : reproche ou regret (tu aurais dû).",s:"Banque anglais"},
{id:"an2-042",t:"ang",q:"Complete: « I'm sorry, I … come to the meeting tomorrow: I'll be on holiday. »",o:["won't be able to","won't can","can't to","don't can"],a:0,e:"Can n'a pas de futur : on emploie will be able to (won't be able to à la forme négative).",s:"Banque anglais"},
// --- Conditionnels ---
{id:"an2-043",t:"ang",q:"Complete: « If you heat ice, it … . »",o:["would melt","melted","had melted","melts"],a:3,e:"Conditionnel zéro (vérité générale) : if + présent, présent.",s:"Banque anglais"},
{id:"an2-044",t:"ang",q:"Complete: « If I had known about the meeting, I … it. »",o:["will attend","would have attended","attended","would attended"],a:1,e:"Conditionnel 3 (irréel du passé) : if + past perfect, would have + participe passé.",s:"Banque anglais"},
{id:"an2-045",t:"ang",q:"Complete: « If she … harder, she would have passed the exam. »",o:["studied","has studied","had studied","would study"],a:2,e:"Conditionnel 3 : if + past perfect (had + participe passé). Pas de would dans la subordonnée en if.",s:"Banque anglais"},
{id:"an2-046",t:"ang",q:"Complete: « Unless you hurry, you … the train. »",o:["will miss","would have missed","would miss","missed"],a:0,e:"Unless = if… not (à moins que) : même construction que le conditionnel 1 (présent, puis will).",s:"Banque anglais"},
{id:"an2-047",t:"ang",q:"Complete: « We will start the meeting as soon as the director … . »",o:["will arrive","arrives","arrived","would arrive"],a:1,e:"Après when, as soon as, before, until à sens futur, on emploie le présent (simple, ou present perfect : as soon as he has arrived), jamais will.",s:"Banque anglais"},
{id:"an2-048",t:"ang",q:"Complete: « What would you do if you … the lottery? »",o:["win","will win","would win","won"],a:3,e:"Conditionnel 2 (hypothèse) : if + prétérit, would + base verbale.",s:"Banque anglais"},
{id:"an2-049",t:"ang",q:"Complete: « I wish I … more free time. »",o:["had","have","will have","would have"],a:0,e:"Wish + prétérit : regret portant sur le présent (j'aimerais avoir).",s:"Banque anglais"},
// --- Voix passive ---
{id:"an2-050",t:"ang",q:"Complete: « English … in many countries around the world. »",o:["speaks","is speaking","has spoken","is spoken"],a:3,e:"Voix passive au présent : be + participe passé (is spoken).",s:"Banque anglais"},
{id:"an2-051",t:"ang",q:"Complete: « A new tax office … in our town next year. »",o:["will build","is building","will be built","builds"],a:2,e:"Passif au futur : will be + participe passé.",s:"Banque anglais"},
{id:"an2-052",t:"ang",q:"Complete: « The suspect … by the police at the moment. »",o:["is questioned","is being questioned","has questioned","questions"],a:1,e:"Passif progressif : be being + participe passé pour une action en cours (at the moment).",s:"Banque anglais"},
{id:"an2-053",t:"ang",q:"Complete: « The accounts … by an independent auditor every year. »",o:["are checked","check","are checking","have checked"],a:0,e:"Passif au présent simple (action habituelle) : are + participe passé ; by introduit l'agent.",s:"Banque anglais"},
{id:"an2-054",t:"ang",q:"Complete: « Three new inspectors … since January. »",o:["were recruited","have recruited","are recruited","have been recruited"],a:3,e:"Since impose le present perfect ; au passif : have been + participe passé.",s:"Banque anglais"},
{id:"an2-055",t:"ang",q:"What is the passive form of « Someone stole my wallet »?",o:["My wallet has stole.","My wallet was stolen.","My wallet stole.","My wallet was stealing."],a:1,e:"Passif du prétérit : was / were + participe passé (steal – stole – stolen).",s:"Banque anglais"},
// --- Discours indirect ---
{id:"an2-056",t:"ang",q:"On Monday, Paul said: « I will call you tomorrow. » On Friday, you report: « Paul said that he … »",o:["will call me tomorrow.","would call you tomorrow.","would call me the next day.","calls me the next day."],a:2,e:"Discours indirect au passé : will devient would, tomorrow devient the next day, et les pronoms s'adaptent (you → me).",s:"Banque anglais"},
{id:"an2-057",t:"ang",q:"Complete: « She asked me where … . »",o:["did I live","do I live","I lived","lived I"],a:2,e:"Question indirecte : ordre sujet + verbe, sans auxiliaire do.",s:"Banque anglais"},
{id:"an2-058",t:"ang",q:"Complete: « He asked me … I had finished the report. »",o:["that","if","what","did"],a:1,e:"Question fermée au discours indirect : if (ou whether) + sujet + verbe.",s:"Banque anglais"},
{id:"an2-059",t:"ang",q:"Complete: « The inspector told me … the documents by Monday. »",o:["send","sending","that send","to send"],a:3,e:"Ordre au discours indirect : tell somebody to + base verbale.",s:"Banque anglais"},
{id:"an2-060",t:"ang",q:"Complete: « He … me that he was leaving the department. »",o:["told","said","spoke","talked"],a:0,e:"Tell + personne (he told me that…) ; say s'emploie sans complément de personne direct (he said that…).",s:"Banque anglais"},
{id:"an2-061",t:"ang",q:"Complete: « She told me not … late. »",o:["be","being","to being","to be"],a:3,e:"Ordre négatif au discours indirect : tell somebody not to + base verbale.",s:"Banque anglais"},
// --- Gérondif ou infinitif ---
{id:"an2-062",t:"ang",q:"Complete: « I really enjoy … in the countryside. »",o:["to walk","walk","walking","to walking"],a:2,e:"Enjoy est suivi du gérondif (-ing), comme avoid, mind, finish, suggest.",s:"Banque anglais"},
{id:"an2-063",t:"ang",q:"Complete: « She decided … her job. »",o:["to leave","leaving","leave","left"],a:0,e:"Decide est suivi de to + base verbale, comme want, hope, refuse, agree.",s:"Banque anglais"},
{id:"an2-064",t:"ang",q:"Complete: « Remember … the door when you leave. »",o:["locking","to lock","lock","locked"],a:1,e:"Remember to do = penser à faire (action à venir) ; remember doing = se souvenir d'avoir fait.",s:"Banque anglais"},
{id:"an2-065",t:"ang",q:"Complete: « I remember … this man before: his face is familiar. »",o:["to meet","meeting","meet","to meeting"],a:1,e:"Remember + -ing = se souvenir d'avoir fait (action passée).",s:"Banque anglais"},
{id:"an2-066",t:"ang",q:"Complete: « He avoided … the journalist's question. »",o:["to answer","answer","answering","to answering"],a:2,e:"Avoid est toujours suivi du gérondif (-ing).",s:"Banque anglais"},
{id:"an2-067",t:"ang",q:"Complete: « I want you … this report by Friday. »",o:["finish","finishing","that you finish","to finish"],a:3,e:"Want + complément + to + base verbale ; on ne dit jamais « I want that you… ».",s:"Banque anglais"},
{id:"an2-068",t:"ang",q:"Complete: « She is used to … up early: she has done it for years. »",o:["getting","get","got","gets"],a:0,e:"Be used to + -ing = avoir l'habitude de ; used to + base verbale = habitude passée révolue.",s:"Banque anglais"},
{id:"an2-069",t:"ang",q:"Complete: « When I was a child, I … play football every Saturday. »",o:["was used to","use to","am used to","used to"],a:3,e:"Used to + base verbale : habitude passée qui n'existe plus.",s:"Banque anglais"},
{id:"an2-070",t:"ang",q:"Complete: « He suggested … to the cinema. »",o:["to go","go","going","went"],a:2,e:"Suggest + -ing (ou suggest that…), jamais suggest + to.",s:"Banque anglais"},
{id:"an2-071",t:"ang",q:"Complete: « My manager made me … the whole report again. »",o:["write","to write","writing","written"],a:0,e:"Make + complément + base verbale sans to (faire faire quelque chose à quelqu'un).",s:"Banque anglais"},
{id:"an2-072",t:"ang",q:"Complete: « Have you finished … the report? »",o:["to write","writing","write","wrote"],a:1,e:"Finish est suivi du gérondif (-ing).",s:"Banque anglais"},
// --- Comparatifs et superlatifs ---
{id:"an2-073",t:"ang",q:"Complete: « This is … building in the city. »",o:["the taller","the tallest","tallest","the most tall"],a:1,e:"Superlatif d'un adjectif court : the + adjectif + -est.",s:"Banque anglais"},
{id:"an2-074",t:"ang",q:"Complete: « The new software is … than the old one. »",o:["more efficient","efficienter","most efficient","more efficienter"],a:0,e:"Adjectif long : more + adjectif + than.",s:"Banque anglais"},
{id:"an2-075",t:"ang",q:"Complete: « Her English is … than mine. »",o:["gooder","more good","better","best"],a:2,e:"Comparatifs irréguliers : good – better – the best ; bad – worse – the worst.",s:"Banque anglais"},
{id:"an2-076",t:"ang",q:"Complete: « The exam was not as difficult … I expected. »",o:["than","that","like","as"],a:3,e:"Comparatif d'égalité : (not) as + adjectif + as.",s:"Banque anglais"},
{id:"an2-077",t:"ang",q:"Complete: « The … you read, the … you learn. »",o:["most / most","more / most","more / more","much / much"],a:2,e:"The more…, the more… : plus…, plus… (comparatif, jamais most).",s:"Banque anglais"},
{id:"an2-078",t:"ang",q:"Complete: « This year, taxes are … higher than last year. »",o:["much","very","more","most"],a:0,e:"Pour renforcer un comparatif : much, far ou a lot (jamais very).",s:"Banque anglais"},
{id:"an2-079",t:"ang",q:"Complete: « There were … people at the meeting than we expected. »",o:["less","fewer","fewest","little"],a:1,e:"Fewer + nom dénombrable pluriel (fewer people) ; less + indénombrable (less money).",s:"Banque anglais"},
{id:"an2-080",t:"ang",q:"Complete: « The weather is getting … . »",o:["more and more bad","worst and worst","badder and badder","worse and worse"],a:3,e:"Comparatif répété pour une progression : worse and worse (de pire en pire), more and more expensive.",s:"Banque anglais"},
// --- Quantifieurs ---
{id:"an2-081",t:"ang",q:"Complete: « I have … friends in London, so I never feel lonely there. »",o:["a little","few","little","a few"],a:3,e:"A few + dénombrable = quelques (sens positif) ; few = peu (sens négatif) ; a little / little + indénombrable.",s:"Banque anglais"},
{id:"an2-082",t:"ang",q:"Complete: « There is very … sugar left: we need to buy some. »",o:["little","few","a few","many"],a:0,e:"Little + indénombrable = peu de ; few et many s'emploient avec un dénombrable pluriel.",s:"Banque anglais"},
{id:"an2-083",t:"ang",q:"Complete: « There aren't … documents on my desk. »",o:["some","much","any","a little"],a:2,e:"Any à la forme négative et dans les questions ouvertes ; much et a little + indénombrable.",s:"Banque anglais"},
{id:"an2-084",t:"ang",q:"Complete: « I need … information about the new tax. »",o:["an","some","many","a few"],a:1,e:"Information est indénombrable en anglais : pas d'article an, pas de pluriel ; quantifieur some ou much.",s:"Banque anglais"},
{id:"an2-085",t:"ang",q:"Complete: « … employee received a bonus this year. »",o:["All","Both","Most","Every"],a:3,e:"Every + nom singulier ; both se construit avec un pluriel, all et most avec un pluriel ou un indénombrable (all employees, most money).",s:"Banque anglais"},
{id:"an2-086",t:"ang",q:"Complete: « He gave me some very good … . »",o:["advices","advice","an advice","advises"],a:1,e:"Advice (conseil) est indénombrable : some advice, a piece of advice. Le verbe est to advise.",s:"Banque anglais"},
{id:"an2-087",t:"ang",q:"Complete: « There are … mistakes in this report: please check it again. »",o:["too many","too much","enough of","too"],a:0,e:"Too many + dénombrable pluriel ; too much + indénombrable.",s:"Banque anglais"},
// --- Articles ---
{id:"an2-088",t:"ang",q:"Complete: « She is … honest woman. »",o:["a","(no article)","an","any"],a:2,e:"An devant un son voyelle : le h de honest, hour, honour est muet.",s:"Banque anglais"},
{id:"an2-089",t:"ang",q:"Which phrase is correct?",o:["a European company","an European company","an university","a hour"],a:0,e:"A ou an dépend du son : a devant le son « you » (a European, a university), an devant un h muet (an hour).",s:"Banque anglais"},
{id:"an2-090",t:"ang",q:"Complete: « He goes to work by … bus. »",o:["the","a","(no article)","an"],a:2,e:"By + moyen de transport s'emploie sans article (by bus, by train, by car).",s:"Banque anglais"},
{id:"an2-091",t:"ang",q:"Complete: « … United Kingdom left the European Union in 2020. »",o:["(no article)","The","A","An"],a:1,e:"The devant les noms de pays formés d'un nom commun ou au pluriel : the United Kingdom, the United States, the Netherlands.",s:"Banque anglais"},
// --- Pronoms relatifs ---
{id:"an2-092",t:"ang",q:"Complete: « The man … lives next door is a tax inspector. »",o:["which","whose","where","who"],a:3,e:"Who pour une personne ; which pour une chose ; that convient aux deux dans une relative déterminative.",s:"Banque anglais"},
{id:"an2-093",t:"ang",q:"Complete: « The report … I wrote yesterday is on your desk. »",o:["who","whose","which","where"],a:2,e:"Which (ou that, ou rien) pour une chose.",s:"Banque anglais"},
{id:"an2-094",t:"ang",q:"Complete: « That's the woman … car was stolen. »",o:["who","whose","which","whom"],a:1,e:"Whose = dont, exprime la possession (whose car = dont la voiture).",s:"Banque anglais"},
{id:"an2-095",t:"ang",q:"Complete: « This is the town … I was born. »",o:["where","which","who","whose"],a:0,e:"Where pour un lieu (= in which).",s:"Banque anglais"},
{id:"an2-096",t:"ang",q:"Complete: « … I need is a long holiday. »",o:["Which","That","Who","What"],a:3,e:"What = ce que (ce dont), sans antécédent ; which a toujours un antécédent.",s:"Banque anglais"},
// --- Question tags ---
{id:"an2-097",t:"ang",q:"Complete: « She can speak Spanish, … ? »",o:["can't she","couldn't she","doesn't she","isn't she"],a:0,e:"Question tag : on reprend l'auxiliaire de la phrase (can) ; phrase affirmative, tag négatif.",s:"Banque anglais"},
{id:"an2-098",t:"ang",q:"Complete: « They didn't come to the meeting, … ? »",o:["didn't they","did they","do they","were they"],a:1,e:"Phrase négative, tag affirmatif, avec le même auxiliaire (did).",s:"Banque anglais"},
{id:"an2-099",t:"ang",q:"Complete: « Let's go, … ? »",o:["will we","don't we","shall we","let we"],a:2,e:"Après Let's…, le question tag est shall we?",s:"Banque anglais"},
{id:"an2-100",t:"ang",q:"Complete: « He has finished his report, … ? »",o:["doesn't he","isn't he","didn't he","hasn't he"],a:3,e:"Has est ici l'auxiliaire du present perfect : on le reprend dans le tag (hasn't he).",s:"Banque anglais"},
{id:"an2-101",t:"ang",q:"Complete: « I'm late, … ? »",o:["aren't I","amn't I","isn't I","am not I"],a:0,e:"Après I am, le tag négatif est aren't I (forme irrégulière).",s:"Banque anglais"},
// --- Phrasal verbs ---
{id:"an2-102",t:"ang",q:"Complete: « Please fill … this form and sign it at the bottom. »",o:["at","of","off","in"],a:3,e:"Fill in a form = remplir un formulaire (en anglais américain : fill out).",s:"Banque anglais"},
{id:"an2-103",t:"ang",q:"What does « to look after » mean?",o:["Chercher","S'occuper de","Regarder derrière","Admirer"],a:1,e:"Look after = s'occuper de ; look for = chercher ; look forward to = avoir hâte de.",s:"Banque anglais"},
{id:"an2-104",t:"ang",q:"What does « to give up » mean?",o:["Distribuer","Donner davantage","Abandonner, renoncer","Se lever"],a:2,e:"Give up = abandonner, renoncer (give up smoking = arrêter de fumer) ; give out = distribuer ; give back = rendre ; get up = se lever.",s:"Banque anglais"},
{id:"an2-105",t:"ang",q:"Complete: « The meeting has been called … because the director is ill. »",o:["out","up","on","off"],a:3,e:"Call off = annuler.",s:"Banque anglais"},
{id:"an2-106",t:"ang",q:"Find the synonym of « to put off » in: « We had to put off the meeting until next week. »",o:["To postpone","To cancel","To prepare","To attend"],a:0,e:"Put off = postpone = reporter, remettre à plus tard ; call off = cancel = annuler.",s:"Banque anglais"},
{id:"an2-107",t:"ang",q:"Complete: « I'm looking … my glasses. Have you seen them? »",o:["after","for","at","up"],a:1,e:"Look for = chercher ; look after = s'occuper de ; look at = regarder.",s:"Banque anglais"},
{id:"an2-108",t:"ang",q:"Complete: « Can you pick me … at the station at six? »",o:["on","off","up","out"],a:2,e:"Pick somebody up = aller chercher quelqu'un (en voiture).",s:"Banque anglais"},
{id:"an2-109",t:"ang",q:"Complete: « We have run … of paper: can you order some? »",o:["off","away","out","over"],a:2,e:"Run out of = être à court de, ne plus avoir de.",s:"Banque anglais"},
{id:"an2-110",t:"ang",q:"Complete: « The government set … a new agency to fight tax fraud. »",o:["up","off","down","in"],a:0,e:"Set up = créer, mettre en place, fonder.",s:"Banque anglais"},
{id:"an2-111",t:"ang",q:"What does « to carry out an audit » mean?",o:["Annuler un contrôle","Réaliser un contrôle","Reporter un contrôle","Contester un contrôle"],a:1,e:"Carry out = effectuer, réaliser (carry out a survey, an investigation).",s:"Banque anglais"},
// --- Verbes irréguliers ---
{id:"an2-112",t:"ang",q:"What is the past participle of « to write »?",o:["wrote","writed","writen","written"],a:3,e:"Write – wrote – written.",s:"Banque anglais"},
{id:"an2-113",t:"ang",q:"What is the past tense (preterit) of « to catch »?",o:["catched","caught","cought","caughten"],a:1,e:"Catch – caught – caught ; même terminaison pour teach – taught – taught.",s:"Banque anglais"},
{id:"an2-114",t:"ang",q:"What is the past tense (preterit) of « to lead »?",o:["leaded","lead","lid","led"],a:3,e:"Lead – led – led (mener, diriger).",s:"Banque anglais"},
{id:"an2-115",t:"ang",q:"Complete: « The price of fuel has … sharply this year. »",o:["rose","raised","risen","rised"],a:2,e:"Rise – rose – risen (intransitif : augmenter) ; raise – raised – raised est transitif (augmenter quelque chose).",s:"Banque anglais"},
{id:"an2-116",t:"ang",q:"What is the past participle of « to choose »?",o:["chosen","chose","choosed","choosen"],a:0,e:"Choose – chose – chosen.",s:"Banque anglais"},
{id:"an2-117",t:"ang",q:"Complete: « She … the electricity bill yesterday. »",o:["payed","pay","paid","paied"],a:2,e:"Pay – paid – paid (et non « payed »).",s:"Banque anglais"},
{id:"an2-118",t:"ang",q:"What is the past tense (preterit) of « to teach »?",o:["teached","thought","tought","taught"],a:3,e:"Teach – taught – taught ; ne pas confondre avec think – thought – thought.",s:"Banque anglais"},
{id:"an2-119",t:"ang",q:"Which of these verbs is regular?",o:["To bring","To explain","To think","To send"],a:1,e:"Explain – explained – explained ; bring – brought, think – thought, send – sent sont irréguliers.",s:"Banque anglais"},
{id:"an2-120",t:"ang",q:"What is the past tense (preterit) of « to fall »?",o:["fell","felt","fallen","falled"],a:0,e:"Fall – fell – fallen ; ne pas confondre avec feel – felt – felt.",s:"Banque anglais"},
// --- Orthographe ---
{id:"an2-121",t:"ang",q:"Which word is spelled correctly?",o:["accomodation","acommodation","accommodation","acomodation"],a:2,e:"Accommodation (logement) : deux c et deux m.",s:"Banque anglais"},
{id:"an2-122",t:"ang",q:"Which word is spelled correctly?",o:["goverment","government","governement","govermnent"],a:1,e:"Government = govern + -ment : n avant le m, sans e intermédiaire (fr : gouvernement).",s:"Banque anglais"},
{id:"an2-123",t:"ang",q:"Which word is spelled correctly?",o:["neccessary","necesary","neccesary","necessary"],a:3,e:"Necessary : un c, deux s.",s:"Banque anglais"},
{id:"an2-124",t:"ang",q:"Which word is spelled correctly?",o:["receive","recieve","receeve","riceive"],a:0,e:"Après c, on écrit ei : receive, receipt, ceiling (« i before e, except after c »).",s:"Banque anglais"},
{id:"an2-125",t:"ang",q:"Which word is spelled correctly?",o:["buisness","business","bussiness","busness"],a:1,e:"Business = busi- + -ness : un seul s au milieu, deux à la fin.",s:"Banque anglais"},
{id:"an2-126",t:"ang",q:"Which word is spelled correctly?",o:["adress","adresse","addresse","address"],a:3,e:"Address : deux d, deux s, sans e final (fr : adresse).",s:"Banque anglais"},
{id:"an2-127",t:"ang",q:"Which word is spelled correctly?",o:["responsability","responsibillity","responsibility","resposibility"],a:2,e:"Responsibility : -ibility, comme responsible (fr : responsabilité).",s:"Banque anglais"},
{id:"an2-128",t:"ang",q:"Which word is spelled correctly?",o:["separate","seperate","separete","sepparate"],a:0,e:"Separate : s-e-p-a-r-a-t-e (moyen mnémotechnique : « there is a rat in separate »).",s:"Banque anglais"},
{id:"an2-129",t:"ang",q:"Which word is spelled correctly?",o:["begining","beggining","beginning","beginnig"],a:2,e:"Begin est accentué sur la dernière syllabe, terminée par voyelle + consonne : on double le n devant -ing (beginning).",s:"Banque anglais"},
{id:"an2-130",t:"ang",q:"Which word is spelled correctly?",o:["developpement","developement","devellopment","development"],a:3,e:"Development : un seul p et pas de e après develop (fr : développement).",s:"Banque anglais"},
{id:"an2-131",t:"ang",q:"Which word is spelled correctly?",o:["embarrassed","embarassed","embarrased","embarased"],a:0,e:"Embarrassed : deux r et deux s.",s:"Banque anglais"},
{id:"an2-132",t:"ang",q:"Complete with the correct spelling: « The accident … at noon. »",o:["occured","occurred","ocurred","occurrd"],a:1,e:"Occur est accentué sur la dernière syllabe : on double le r au prétérit (occurred, occurring).",s:"Banque anglais"},
{id:"an2-133",t:"ang",q:"Complete: « The company has changed … name. »",o:["its","it's","its'","it is"],a:0,e:"Its = possessif (son, sa, ses) ; it's = it is ou it has.",s:"Banque anglais"},
{id:"an2-134",t:"ang",q:"Complete: « … going to the meeting tomorrow. »",o:["Their","There","Theyr","They're"],a:3,e:"They're = they are ; their = leur(s) ; there = là, il y a.",s:"Banque anglais"},
{id:"an2-135",t:"ang",q:"Complete: « Be careful not to … your keys. »",o:["loose","loss","lose","lost"],a:2,e:"To lose = perdre ; loose = desserré, ample ; loss = perte (nom).",s:"Banque anglais"},
{id:"an2-136",t:"ang",q:"Complete: « I … you to read the contract carefully. »",o:["advice","advise","advices","advize"],a:1,e:"Advise (verbe, avec s) ; advice (nom indénombrable, avec c).",s:"Banque anglais"},
// --- Faux amis ---
{id:"an2-137",t:"ang",q:"« The children pretended to be asleep when their mother came in. » What does « pretended » mean here?",o:["Ont affirmé","Ont refusé","Ont fait semblant","Ont essayé"],a:2,e:"Faux ami : to pretend = faire semblant ; prétendre (affirmer) = to claim.",s:"Banque anglais"},
{id:"an2-138",t:"ang",q:"« I suddenly realized I had forgotten my keys. » What does « realized » mean?",o:["Je me suis rendu compte","J'ai imaginé","J'ai regretté","J'ai prouvé"],a:0,e:"To realize = se rendre compte ; réaliser (un projet) = to carry out, to achieve.",s:"Banque anglais"},
{id:"an2-139",t:"ang",q:"« She finally achieved her goal. » What does « achieved » mean?",o:["Achevé","Acheté","Abandonné","Atteint"],a:3,e:"Faux ami : to achieve = atteindre, réaliser ; achever = to finish, to complete.",s:"Banque anglais"},
{id:"an2-140",t:"ang",q:"« Please send your résumé and a cover letter to the HR department. » What is a « résumé » here?",o:["Un résumé","Un CV","Un rapport d'activité","Un justificatif de domicile"],a:1,e:"En anglais américain, résumé = CV (en anglais britannique : CV) ; un résumé (synthèse) = a summary.",s:"Banque anglais"},
{id:"an2-141",t:"ang",q:"« What's on the agenda for today's meeting? » What does « agenda » mean?",o:["Le carnet de rendez-vous","Le compte rendu","L'ordre du jour","La liste des participants"],a:2,e:"Faux ami : agenda = ordre du jour ; un agenda (carnet) = a diary ou a planner.",s:"Banque anglais"},
{id:"an2-142",t:"ang",q:"« A nurse assisted the surgeon during the operation. » What does « assisted » mean?",o:["A assisté (était présent sans participer)","A aidé","A remplacé","A observé"],a:1,e:"To assist = aider ; assister à (être présent) = to attend.",s:"Banque anglais"},
{id:"an2-143",t:"ang",q:"What does « deception » mean?",o:["Tromperie","Déception","Réception","Décision"],a:0,e:"Faux ami : deception = tromperie ; déception = disappointment.",s:"Banque anglais"},
{id:"an2-144",t:"ang",q:"« The new office is in a great location. » What does « location » mean?",o:["Location (bail)","Loyer","Logement","Emplacement"],a:3,e:"Location = emplacement, lieu ; la location (bail) = rental, renting.",s:"Banque anglais"},
{id:"an2-145",t:"ang",q:"« My boss was very sympathetic when my father was ill. » What does « sympathetic » mean?",o:["Compréhensif, compatissant","Sympathique","Symbolique","Bavard"],a:0,e:"Faux ami : sympathetic = compatissant, compréhensif ; sympathique = nice, friendly.",s:"Banque anglais"},
{id:"an2-146",t:"ang",q:"« The journey from Paris to Lyon takes two hours by train. » What does « journey » mean?",o:["La journée","Le trajet, le voyage","Le journal","Le jour férié"],a:1,e:"Journey = trajet, voyage ; une journée = a day.",s:"Banque anglais"},
{id:"an2-147",t:"ang",q:"« Tax fraud is a major issue for the government. » What does « issue » mean here?",o:["Une issue (sortie)","Une solution","Un problème, un enjeu","Un résultat"],a:2,e:"Issue = question, problème, enjeu ; une issue (sortie) = an exit ; une issue (dénouement) = an outcome.",s:"Banque anglais"},
{id:"an2-148",t:"ang",q:"« She passed her driving test. » What does it mean?",o:["Elle s'est présentée à son permis, sans préciser le résultat.","Elle a échoué au permis.","Elle a révisé son permis.","Elle a réussi son permis."],a:3,e:"To pass an exam = réussir ; passer un examen = to take (ou sit) an exam.",s:"Banque anglais"},
{id:"an2-149",t:"ang",q:"« The actual cost was higher than the estimate. » What does « actual » mean?",o:["Actuel","Prévu","Réel","Total"],a:2,e:"Faux ami : actual = réel, effectif ; actuel = current.",s:"Banque anglais"},
{id:"an2-150",t:"ang",q:"« The minister resigned last week. » What does « resigned » mean?",o:["S'est résigné","A démissionné","A été réélu","A signé de nouveau"],a:1,e:"To resign = démissionner ; se résigner = to resign oneself (to something).",s:"Banque anglais"},
// --- Finances publiques, fiscalité, comptabilité, administration ---
{id:"an2-151",t:"ang",q:"What's the English for « remboursement d'impôt »?",o:["A tax return","A tax rate","A tax bracket","A tax refund"],a:3,e:"Tax refund = remboursement ; tax return = déclaration de revenus ; tax rate = taux d'imposition.",s:"Banque anglais"},
{id:"an2-152",t:"ang",q:"What does « tax evasion » mean?",o:["La fraude fiscale (illégale)","L'optimisation fiscale (légale)","L'exonération d'impôt","Le crédit d'impôt"],a:0,e:"Tax evasion = fraude fiscale, illégale ; tax avoidance = optimisation fiscale, légale mais parfois abusive.",s:"Banque anglais"},
{id:"an2-153",t:"ang",q:"What's the English for « optimisation fiscale » (réduire son impôt par des moyens légaux)?",o:["Tax evasion","Tax fraud","Tax avoidance","Tax collection"],a:2,e:"Tax avoidance = optimisation fiscale ; tax evasion et tax fraud désignent la fraude ; tax collection = recouvrement.",s:"Banque anglais"},
{id:"an2-154",t:"ang",q:"What does « tax haven » mean?",o:["Niche fiscale","Bouclier fiscal","Crédit d'impôt","Paradis fiscal"],a:3,e:"Haven = refuge, abri. Niche fiscale = tax loophole ou tax break ; crédit d'impôt = tax credit.",s:"Banque anglais"},
{id:"an2-155",t:"ang",q:"What does « corporate tax » mean?",o:["L'impôt sur le revenu","L'impôt sur les sociétés","La taxe foncière","Les droits d'enregistrement"],a:1,e:"Corporate tax (corporation tax au Royaume-Uni) = impôt sur les sociétés ; income tax = impôt sur le revenu.",s:"Banque anglais"},
{id:"an2-156",t:"ang",q:"What's the English for « droits de douane »?",o:["Customs duties","Custom rights","Duty-free","Excise duties"],a:0,e:"Customs (toujours avec s) = la douane ; duty = droit, taxe. Duty-free = hors taxes ; excise duties = droits d'accise.",s:"Banque anglais"},
{id:"an2-157",t:"ang",q:"What does « tax bracket » mean?",o:["Taux réduit","Tranche d'imposition","Abattement","Niche fiscale"],a:1,e:"Tax bracket = tranche du barème ; tax rate = taux ; allowance = abattement.",s:"Banque anglais"},
{id:"an2-158",t:"ang",q:"What's the English for « prélèvement à la source » (de l'impôt sur le revenu)?",o:["Withholding tax","Direct debit","Tax deduction","Sales tax"],a:0,e:"Withholding tax = retenue à la source ; direct debit = prélèvement automatique sur un compte ; tax deduction = déduction fiscale.",s:"Banque anglais"},
{id:"an2-159",t:"ang",q:"« The budget deficit narrowed last year. » What does « narrowed » mean?",o:["S'est creusé","A été publié","S'est réduit","A été voté"],a:2,e:"Narrow = (se) réduire, (se) resserrer ; widen = (se) creuser, s'élargir.",s:"Banque anglais"},
{id:"an2-160",t:"ang",q:"What's the English for « les dépenses publiques »?",o:["Public spendings","Public expanses","Public dispenses","Public spending"],a:3,e:"Spending est indénombrable (jamais de s) ; on dit aussi public expenditure.",s:"Banque anglais"},
{id:"an2-161",t:"ang",q:"« The government announced spending cuts. » What does it mean?",o:["Des hausses de dépenses","Des réductions de dépenses","Des coupures de courant","Des baisses d'impôts"],a:1,e:"Cut = réduction, coupe ; spending = dépenses. Des baisses d'impôts = tax cuts.",s:"Banque anglais"},
{id:"an2-162",t:"ang",q:"What's the English for « recettes fiscales »?",o:["Tax revenue","Tax recipes","Tax rents","Tax gains"],a:0,e:"Revenue = recettes (de l'État) ; on dit aussi tax receipts ; recipe = recette de cuisine.",s:"Banque anglais"},
{id:"an2-163",t:"ang",q:"What's the English for « compte de résultat »?",o:["Balance sheet","Result account","Cash flow statement","Income statement"],a:3,e:"Income statement (ou profit and loss account) = compte de résultat ; balance sheet = bilan.",s:"Banque anglais"},
{id:"an2-164",t:"ang",q:"What does « fixed assets » mean?",o:["Les stocks","Les créances clients","Les immobilisations","Les capitaux propres"],a:2,e:"Fixed assets = actif immobilisé (immobilisations) ; current assets = actif circulant (stocks, créances, trésorerie).",s:"Banque anglais"},
{id:"an2-165",t:"ang",q:"What does « equity » mean in a balance sheet?",o:["L'équité","Les dettes financières","La trésorerie","Les capitaux propres"],a:3,e:"Equity (shareholders' equity) = capitaux propres. Faux ami : équité = fairness.",s:"Banque anglais"},
{id:"an2-166",t:"ang",q:"What's the English for « commissaire aux comptes »?",o:["Accountant","Account commissioner","Auditor","Treasurer"],a:2,e:"Auditor (statutory auditor) = commissaire aux comptes, qui certifie les comptes ; accountant = comptable.",s:"Banque anglais"},
{id:"an2-167",t:"ang",q:"What's the French for « accountant »?",o:["Conteur","Comptable","Banquier","Caissier"],a:1,e:"Accountant = comptable ; accounting = comptabilité ; cashier = caissier.",s:"Banque anglais"},
{id:"an2-168",t:"ang",q:"What's the French for « invoice »?",o:["Facture","Devis","Bon de commande","Reçu"],a:0,e:"Invoice = facture ; quote (ou estimate) = devis ; purchase order = bon de commande ; receipt = reçu.",s:"Banque anglais"},
{id:"an2-169",t:"ang",q:"« Keep the receipt in case you want to return the item. » What does « receipt » mean here?",o:["Le ticket de caisse","La recette","Le bon de commande","Le devis"],a:0,e:"Receipt = reçu, ticket de caisse (le p ne se prononce pas) ; recipe = recette de cuisine. Au pluriel, en finances, receipts peut aussi désigner les recettes encaissées (tax receipts), mais pas ici.",s:"Banque anglais"},
{id:"an2-170",t:"ang",q:"What's the English for « fonctionnaire »?",o:["Civilian","Civic server","Civil servant","Function holder"],a:2,e:"Civil servant = fonctionnaire ; the civil service = la fonction publique ; a civilian = un civil.",s:"Banque anglais"},
{id:"an2-171",t:"ang",q:"What's the English for « ministère »?",o:["Minister","Ministery","Ministration","Ministry"],a:3,e:"Ministry = ministère ; minister = ministre (Minister for the Economy).",s:"Banque anglais"},
{id:"an2-172",t:"ang",q:"What's the English for « le Trésor public »?",o:["The Treasure","The Treasury","The Thesaurus","The Tresory"],a:1,e:"Treasury = Trésor (administration financière de l'État) ; treasure = trésor (objets précieux).",s:"Banque anglais"},
{id:"an2-173",t:"ang",q:"In finance, what is a « bond »?",o:["Une action","Un bon d'achat","Une obligation","Un dividende"],a:2,e:"Bond = obligation (titre de dette) ; share = action ; voucher = bon d'achat.",s:"Banque anglais"},
{id:"an2-174",t:"ang",q:"« The central bank raised interest rates. » What does it mean?",o:["La banque centrale a baissé les taux d'intérêt.","La banque centrale a relevé les taux de change.","La banque centrale a suscité l'intérêt des marchés.","La banque centrale a relevé les taux d'intérêt."],a:3,e:"To raise = relever, augmenter ; interest rate = taux d'intérêt ; exchange rate = taux de change.",s:"Banque anglais"},
{id:"an2-175",t:"ang",q:"« Inflation rose to 3% last year. » What does it mean?",o:["L'inflation a augmenté de 3 points.","L'inflation est montée jusqu'à 3 %.","L'inflation a baissé à 3 %.","L'inflation est restée stable à 3 %."],a:1,e:"Rise to = atteindre (niveau d'arrivée) ; rise by = augmenter de (écart).",s:"Banque anglais"},
{id:"an2-176",t:"ang",q:"What does « GDP » stand for?",o:["Gross Domestic Product","General Domestic Product","Gross Development Product","Global Domestic Production"],a:0,e:"GDP = PIB (produit intérieur brut) ; gross = brut.",s:"Banque anglais"},
{id:"an2-177",t:"ang",q:"« The company paid a dividend to its shareholders. » What is a dividend?",o:["Une part du bénéfice versée aux actionnaires","Un prêt accordé aux actionnaires","Un impôt payé par les actionnaires","Une amende infligée aux actionnaires"],a:0,e:"Dividend = dividende, part du bénéfice distribuée ; shareholder = actionnaire.",s:"Banque anglais"},
{id:"an2-178",t:"ang",q:"What does « payroll » mean?",o:["Le registre des factures","La caisse enregistreuse","La paie, la masse salariale","Le relevé bancaire"],a:2,e:"Payroll = paie, ensemble des salaires versés par l'employeur (payroll tax = taxe sur les salaires).",s:"Banque anglais"},
{id:"an2-179",t:"ang",q:"Complete: « He had to pay a €135 … for speeding. »",o:["fee","fare","fair","fine"],a:3,e:"Fine = amende ; fee = frais, honoraires ; fare = prix du billet (transport) ; fair = juste, équitable.",s:"Banque anglais"},
{id:"an2-180",t:"ang",q:"Complete: « The lawyer's … are very high. »",o:["fines","fees","fares","fairs"],a:1,e:"Fees = honoraires, frais (school fees, bank fees) ; fines = amendes.",s:"Banque anglais"},
{id:"an2-181",t:"ang",q:"What's the English for « pénalité de retard » (sur un paiement)?",o:["Delay punishment","Retard fine","Late payment penalty","Lately penalty"],a:2,e:"Penalty = pénalité, sanction ; late payment = paiement tardif. Lately = récemment.",s:"Banque anglais"},
{id:"an2-182",t:"ang",q:"« He took out a loan to buy a flat. » What does « loan » mean?",o:["Une location","Un prêt","Un loyer","Une remise"],a:1,e:"Loan = prêt (take out a loan = contracter un emprunt) ; rent = loyer.",s:"Banque anglais"},
{id:"an2-183",t:"ang",q:"« The company made a loss last year. » What does it mean?",o:["L'entreprise a subi une perte.","L'entreprise a fait faillite.","L'entreprise a réalisé un bénéfice.","L'entreprise a perdu un procès."],a:0,e:"Make a loss = être en perte (contraire : make a profit) ; go bankrupt = faire faillite.",s:"Banque anglais"},
{id:"an2-184",t:"ang",q:"« Parliament passed the budget in December. » What does « passed » mean?",o:["A rejeté","A dépassé","A présenté","A adopté"],a:3,e:"To pass a law, a budget = adopter, voter ; to reject = rejeter.",s:"Banque anglais"},
{id:"an2-185",t:"ang",q:"« The bill was passed by Parliament. » What does « bill » mean here?",o:["Une facture","Un billet de banque","Une addition","Un projet de loi"],a:3,e:"Dans un contexte parlementaire, bill = projet ou proposition de loi ; une fois adopté, il devient an Act.",s:"Banque anglais"},
{id:"an2-186",t:"ang",q:"« You must file your tax return online. » What does « file » mean here?",o:["Classer","Faire la queue","Déposer, remettre","Limer"],a:2,e:"To file a tax return = déposer sa déclaration ; to file a document peut aussi signifier classer, mais pas ici.",s:"Banque anglais"},
{id:"an2-187",t:"ang",q:"Complete: « How much do I … you for the repair? »",o:["owe","own","due","borrow"],a:0,e:"To owe = devoir (de l'argent) ; to own = posséder ; to borrow = emprunter.",s:"Banque anglais"},
{id:"an2-188",t:"ang",q:"Complete: « Can you … me €20 until Friday? »",o:["borrow","lend","owe","rent"],a:1,e:"Lend = prêter ; borrow = emprunter (borrow something from somebody).",s:"Banque anglais"},
{id:"an2-189",t:"ang",q:"Complete: « The … pays the salaries; the employees receive them. »",o:["employee","employment","employer","employed"],a:2,e:"Employer = employeur ; employee = salarié (le suffixe -ee désigne celui qui subit l'action).",s:"Banque anglais"},
// --- Traduction ---
{id:"an2-190",t:"ang",q:"What's the English for: « Pouvez-vous m'envoyer la facture d'ici vendredi ? »",o:["Can you send me the invoice by Friday?","Can you send me the invoice until Friday?","Can you send to me the invoice by Friday?","Can you sent me the invoice by Friday?"],a:0,e:"By = au plus tard, d'ici ; send somebody something (sans to devant le premier complément) ; can + base verbale (send).",s:"Banque anglais"},
{id:"an2-191",t:"ang",q:"What's the English for: « Je suis d'accord avec vous. »",o:["I am agree with you.","I agree you.","I do agreed with you.","I agree with you."],a:3,e:"To agree est un verbe : pas d'auxiliaire be (I agree, jamais « I am agree »).",s:"Banque anglais"},
{id:"an2-192",t:"ang",q:"What's the English for: « Ça fait longtemps que tu attends ? »",o:["Are you waiting since long?","Have you been waiting long?","Do you wait since a long time?","Have you waited since long?"],a:1,e:"Action commencée dans le passé et qui dure encore : present perfect continuous ; since ne s'emploie pas avec long.",s:"Banque anglais"},
{id:"an2-193",t:"ang",q:"What's the English for: « Il pleuvait quand je suis sorti. »",o:["It was raining when I go out.","It was raining when I was went out.","It was raining when I went out.","It were raining when I went out."],a:2,e:"Imparfait de description : past continuous (was raining) ; action ponctuelle : prétérit (went out).",s:"Banque anglais"},
{id:"an2-194",t:"ang",q:"What's the English for: « Je n'ai jamais vu ce document. »",o:["I have never saw this document.","I haven't never seen this document.","I am never seen this document.","I have never seen this document."],a:3,e:"Present perfect : have + participe passé (seen) ; une seule négation en anglais (never suffit).",s:"Banque anglais"},
{id:"an2-195",t:"ang",q:"What's the English for: « Il faut que tu remplisses ce formulaire. »",o:["It must that you fill in this form.","You have to fill in this form.","You have fill in this form.","You must to fill in this form."],a:1,e:"Obligation : have to + base verbale, ou must + base verbale (sans to).",s:"Banque anglais"},
{id:"an2-196",t:"ang",q:"What's the English for: « Le ministre a été interviewé hier. »",o:["The minister was interviewed yesterday.","The minister has been interviewed yesterday.","The minister was interviewing yesterday.","The minister is interviewed yesterday."],a:0,e:"Yesterday impose le prétérit ; passif : was + participe passé.",s:"Banque anglais"},
{id:"an2-197",t:"ang",q:"What's the English for: « Si j'avais su, je serais venu. »",o:["If I had known, I would have come.","If I had knew, I would have come.","If I had known, I will have come.","If I have known, I would have come."],a:0,e:"Irréel du passé : if + past perfect (had known), would have + participe passé.",s:"Banque anglais"},
{id:"an2-198",t:"ang",q:"What's the English for: « Combien de temps faut-il pour aller à la gare ? »",o:["How long does it takes to get to the station?","How long it takes to get to the station?","How long does it take to get to the station?","How long does it take for go to the station?"],a:2,e:"It takes + durée + to + verbe ; dans la question : does it take (base verbale après does).",s:"Banque anglais"},
{id:"an2-199",t:"ang",q:"What's the English for: « On m'a dit de venir à 9 heures. »",o:["I was said to come at 9 o'clock.","I was told coming at 9 o'clock.","I was told to come in 9 o'clock.","I was told to come at 9 o'clock."],a:3,e:"« On » se traduit souvent par un passif : tell somebody to do → I was told to do ; at + heure.",s:"Banque anglais"},
{id:"an2-200",t:"ang",q:"What's the English for: « Il est interdit de fumer ici. »",o:["It is forbid to smoke here.","Smoking is not allowed here.","Smoking is not allow here.","It is not allowed smoke here."],a:1,e:"Be allowed (participe passé) ; le verbe forbid fait forbade – forbidden. Le gérondif peut être sujet (smoking).",s:"Banque anglais"},
// --- Vocabulaire et grammaire divers ---
{id:"an2-201",t:"ang",q:"Complete: « Everybody can … a mistake. »",o:["do","make","take","have"],a:1,e:"Make a mistake, make an effort, make money ; do homework, do business, do the shopping.",s:"Banque anglais"},
{id:"an2-202",t:"ang",q:"Complete: « We … business with many foreign companies. »",o:["make","take","do","get"],a:2,e:"Do business (with) = faire des affaires ; make s'emploie pour fabriquer ou produire (make a profit).",s:"Banque anglais"},
{id:"an2-203",t:"ang",q:"Complete: « The government decided to … taxes on tobacco. »",o:["rise","arise","rose","raise"],a:3,e:"Raise (transitif) = augmenter quelque chose ; rise (intransitif) = augmenter, monter : prices rise.",s:"Banque anglais"},
{id:"an2-204",t:"ang",q:"Complete: « He isn't old … to vote. »",o:["enough","too","so","such"],a:0,e:"Enough se place après l'adjectif (old enough) et avant le nom (enough money).",s:"Banque anglais"},
{id:"an2-205",t:"ang",q:"Complete: « It was … boring meeting that I nearly fell asleep. »",o:["so","such a","so a","such"],a:1,e:"Such a + adjectif + nom singulier dénombrable ; so + adjectif seul (so boring).",s:"Banque anglais"},
{id:"an2-206",t:"ang",q:"Complete: « … the rain, we went for a walk. »",o:["Although","However","Despite","Even"],a:2,e:"Despite (ou in spite of) + nom ; although + sujet + verbe ; however = cependant.",s:"Banque anglais"},
{id:"an2-207",t:"ang",q:"Complete: « The news … very good today. »",o:["are","were","have","is"],a:3,e:"News est indénombrable et singulier malgré son s final.",s:"Banque anglais"},
{id:"an2-208",t:"ang",q:"Complete: « I haven't received the invoice … . »",o:["yet","already","still","ever"],a:0,e:"Yet (pas encore) en fin de phrase négative ; already s'emploie à l'affirmative ; still se placerait avant haven't.",s:"Banque anglais"},
{id:"an2-209",t:"ang",q:"Complete: « Someone … my wallet on the train. »",o:["robbed","stole","stolen","stealed"],a:1,e:"Steal something (voler un objet) ; rob somebody or a place (voler quelqu'un, dévaliser une banque).",s:"Banque anglais"},
{id:"an2-210",t:"ang",q:"Complete: « My wife's brother is my … . »",o:["brother-in-law","stepbrother","half-brother","cousin"],a:0,e:"Parenté par alliance : -in-law (brother-in-law = beau-frère) ; stepbrother = fils du conjoint d'un parent ; half-brother = demi-frère (un parent commun).",s:"Banque anglais"},
// --- Synonymes et contraires ---
{id:"an2-211",t:"ang",q:"Find the synonym of « to purchase ».",o:["To sell","To rent","To buy","To borrow"],a:2,e:"Purchase = buy = acheter (registre plus soutenu).",s:"Banque anglais"},
{id:"an2-212",t:"ang",q:"Find the synonym of « to cut » in: « The government wants to cut public spending. »",o:["To increase","To share","To spend","To reduce"],a:3,e:"To cut = to reduce = réduire.",s:"Banque anglais"},
{id:"an2-213",t:"ang",q:"Find the opposite of « expensive ».",o:["Costly","Cheap","Pricey","Dear"],a:1,e:"Cheap = bon marché ; costly, pricey et dear (au Royaume-Uni) sont des synonymes d'expensive.",s:"Banque anglais"},
{id:"an2-214",t:"ang",q:"Find the synonym of « accurate » in: « The figures in the report are accurate. »",o:["Approximate","Careless","Vague","Precise"],a:3,e:"Accurate = précis, exact ; approximate = approximatif.",s:"Banque anglais"},
{id:"an2-215",t:"ang",q:"Find the synonym of « currently ».",o:["At present","Actually","Eventually","Lately"],a:0,e:"Currently = at present = actuellement ; actually = en fait ; eventually = finalement ; lately = ces derniers temps.",s:"Banque anglais"},
{id:"an2-216",t:"ang",q:"Find the synonym of « to deal with » in: « She deals with tax complaints. »",o:["To avoid","To sell","To handle","To delay"],a:2,e:"Deal with = handle = traiter, s'occuper de.",s:"Banque anglais"}
);
